import java.util.Scanner;

public class Main {
    static final int MAXN = 266666;
    static long[] fact = new long[MAXN];
    static long[] inv_fact = new long[MAXN];
    static long[][] dp_arr = new long[30][22];
    static long[][] a_data = new long[18][1 << 17];
    static long[] b_vals = new long[1 << 17];
    static int M;

    static long q_pow(long base, long exp) {
        long res = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * cur % M;
            cur = cur * cur % M;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        M = sc.nextInt();

        if (n % 2 != 0) {
            System.out.println(q_pow(k, n));
            sc.close();
            return;
        }

        fact[0] = 1;
        for (int i = 1; i <= n; ++i) {
            fact[i] = fact[i - 1] * i % M;
        }

        inv_fact[n] = q_pow(fact[n], M - 2);
        for (int i = n - 1; i >= 0; --i) {
            inv_fact[i] = inv_fact[i + 1] * (i + 1) % M;
        }

        int half = n >> 1;
        for (int i = 0; i <= half; ++i) {
            int popcnt = Integer.bitCount(i);
            a_data[popcnt][i] = inv_fact[i * 2];
        }

        for (int i = 0; i < 17; ++i) {
            for (int j = 0; j < 17; ++j) {
                for (int u = 0; u < (1 << 17); ++u) {
                    if (((u >> j) & 1) == 1) {
                        a_data[i][u] += a_data[i][u ^ (1 << j)];
                    }
                }
            }
        }

        for (int i = 0; i < 17; ++i) {
            for (int u = 0; u < (1 << 17); ++u) {
                a_data[i][u] %= M;
            }
        }

        int popcnt_half = Integer.bitCount(half);
        for (int i = 0; i < (1 << 17); ++i) {
            for (int j = 0; j <= 17; ++j) {
                for (int u = 0; u <= 17; ++u) {
                    for (int v = 0; v + u <= 17; ++v) {
                        dp_arr[j][u + v] = 0;
                    }
                }
            }
            for (int j = 0; j <= 17; ++j) {
                for (int u = 0; u <= 17; ++u) {
                    for (int v = 0; v <= 17; ++v) {
                        dp_arr[j][v] = 0;
                    }
                }
            }
            for (int j = 0; j <= 17; ++j) {
                for (int u = 0; u <= 17; ++u) {
                    for (int v = 0; v <= 17; ++v) {
                        dp_arr[j][v] = 0;
                    }
                }
            }
            for (int j = 0; j <= 17; ++j) {
                for (int u = 0; u <= 17; ++u) {
                    for (int v = 0; v <= 17; ++v) {
                        dp_arr[j][v] = 0;
                    }
                }
            }
            // Initialize dp
            for (int j = 0; j <= 17; ++j) {
                for (int u = 0; u <= 17; ++u) {
                    for (int v = 0; v <= 17; ++v) {
                        dp_arr[j][v] = 0;
                    }
                }
            }
            dp_arr[0][0] = 1;
            for (int j = 1; j <= k; ++j) {
                for (int u = 0; u <= 17; ++u) {
                    for (int v = 0; v + u <= 17; ++v) {
                        long val = a_data[u][i] * dp_arr[j - 1][v] % M;
                        dp_arr[j][u + v] = (dp_arr[j][u + v] + val) % M;
                    }
                }
                if ((u & 7) == 0) {
                    for (int v = 0; v <= 17; ++v) {
                        dp_arr[j][v] %= M;
                    }
                }
            }
            for (int v = 0; v <= 17; ++v) {
                dp_arr[k][v] %= M;
            }
            b_vals[i] = dp_arr[k][popcnt_half];
        }

        for (int i = 0; i < 17; ++i) {
            for (int j = 0; j < (1 << 17); ++j) {
                if (((j >> i) & 1) == 1) {
                    b_vals[j] -= b_vals[j ^ (1 << i)];
                }
            }
        }

        long ans = ((q_pow(k, n * 2) - b_vals[n] * fact[n * 2]) % M + M) % M;
        System.out.println(ans);
        sc.close();
    }
}

